import { parseCommandLine } from './argparse-lite.mjs';
import { buildFixedBytes, buildInt8ul, buildInt16ul } from './construct-lite.mjs';
import { toPythonBytesLiteral } from './python-bytes.mjs';

function pythonModulo(value, divisor) {
  return ((value % divisor) + divisor) % divisor;
}

function buildOutputs(args) {
  const format1 = buildInt8ul(args.a);
  const format2 = buildInt16ul(args.b);
  const format3 = buildFixedBytes(args.d, Buffer.from(args.c, 'utf8'));
  const format4 = buildInt8ul(args.f);
  const format5 = buildFixedBytes(args.g, Buffer.from(args.e, 'utf8'));
  const format6 = buildInt8ul(pythonModulo(args.f + args.g, 256));
  const format7 = buildInt8ul(pythonModulo(args.a + args.b, 256));

  return [format1, format2, format3, format4, format5, format6, format7];
}

function writeLines(lines, stream) {
  for (const line of lines) {
    stream.write(`${line}\n`);
  }
}

export function main(argv = process.argv) {
  const parseResult = parseCommandLine(argv);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.output);
    return parseResult.exitCode;
  }

  if (parseResult.kind === 'error') {
    process.stderr.write(parseResult.output);
    return parseResult.exitCode;
  }

  try {
    const outputs = buildOutputs(parseResult.args).map((buffer) => toPythonBytesLiteral(buffer));
    writeLines(outputs, process.stdout);
    return 0;
  } catch (error) {
    if (error instanceof Error) {
      process.stderr.write(`${error.name}: ${error.message}\n`);
      return 1;
    }

    throw error;
  }
}

import { run } from "./lib/test17/run.mjs";

export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
  return run(argv, scriptPath);
}

const exitCode = main();

if (exitCode !== 0) {
  process.exitCode = exitCode;
}

import {
  ARGUMENT_DEFINITIONS,
  ARGUMENTS_BY_NAME,
  formatHelp,
  formatUsage,
  getProgramName,
} from './cli-spec.mjs';

const DECIMAL_INTEGER_PATTERN = /^[+-]?\d(?:_?\d)*$/;
const NEGATIVE_NUMBER_PATTERN = /^-\d(?:_?\d)*(?:\.\d(?:_?\d)*)?$/;

function isNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function looksLikeOptionToken(token) {
  return token.startsWith('-') && !isNegativeNumberToken(token);
}

function parseIntegerValue(optionName, rawValue) {
  if (!DECIMAL_INTEGER_PATTERN.test(rawValue)) {
    throw createCliError(`argument ${optionName}: invalid int value: '${rawValue}'`);
  }

  const normalized = rawValue.replace(/_/g, '');
  const parsed = Number(normalized);
  if (!Number.isInteger(parsed)) {
    throw createCliError(`argument ${optionName}: invalid int value: '${rawValue}'`);
  }

  return parsed;
}

function createCliError(message) {
  const error = new Error(message);
  error.name = 'CliParseError';
  return error;
}

function createResult(kind, programName, payload = {}) {
  return {
    kind,
    programName,
    ...payload,
  };
}

function collectUnknownTokenExtras(tokens, index, extras) {
  const token = tokens[index];
  extras.push(token);

  const hasInlineValue = token.includes('=');
  if (hasInlineValue) {
    return index;
  }

  const nextToken = tokens[index + 1];
  if (nextToken === undefined) {
    return index;
  }

  if (looksLikeOptionToken(nextToken)) {
    return index;
  }

  extras.push(nextToken);
  return index + 1;
}

function coerceValue(definition, rawValue) {
  if (definition.type === 'int') {
    return parseIntegerValue(definition.name, rawValue);
  }

  return rawValue;
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = Array.isArray(argv) ? argv.slice(2) : [];
  const parsedValues = {};
  const extras = [];

  try {
    for (let index = 0; index < tokens.length; index += 1) {
      const token = tokens[index];

      if (token === '-h' || token === '--help') {
        return createResult('help', programName, { output: formatHelp(programName), exitCode: 0 });
      }

      if (token.startsWith('--')) {
        const equalsIndex = token.indexOf('=');
        const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
        const definition = ARGUMENTS_BY_NAME[optionName];

        if (definition === undefined) {
          index = collectUnknownTokenExtras(tokens, index, extras);
          continue;
        }

        let rawValue;
        if (equalsIndex !== -1) {
          rawValue = token.slice(equalsIndex + 1);
        } else {
          const nextToken = tokens[index + 1];
          if (nextToken === undefined || looksLikeOptionToken(nextToken)) {
            throw createCliError(`argument ${optionName}: expected one argument`);
          }

          rawValue = nextToken;
          index += 1;
        }

        parsedValues[optionName] = coerceValue(definition, rawValue);
        continue;
      }

      if (token.startsWith('-')) {
        index = collectUnknownTokenExtras(tokens, index, extras);
        continue;
      }

      extras.push(token);
    }
  } catch (error) {
    if (error && error.name === 'CliParseError') {
      return createResult('error', programName, {
        output: `${formatUsage(programName)}\n${programName}: error: ${error.message}\n`,
        exitCode: 2,
      });
    }

    throw error;
  }

  const missing = ARGUMENT_DEFINITIONS
    .map((definition) => definition.name)
    .filter((name) => parsedValues[name] === undefined);

  if (missing.length > 0) {
    return createResult('error', programName, {
      output: `${formatUsage(programName)}\n${programName}: error: the following arguments are required: ${missing.join(', ')}\n`,
      exitCode: 2,
    });
  }

  if (extras.length > 0) {
    return createResult('error', programName, {
      output: `${formatUsage(programName)}\n${programName}: error: unrecognized arguments: ${extras.join(' ')}\n`,
      exitCode: 2,
    });
  }

  return createResult('ok', programName, {
    args: {
      a: parsedValues['--a'],
      b: parsedValues['--b'],
      c: parsedValues['--c'],
      d: parsedValues['--d'],
      e: parsedValues['--e'],
      f: parsedValues['--f'],
      g: parsedValues['--g'],
    },
    exitCode: 0,
  });
}

export const ARGUMENT_DEFINITIONS = [
  { name: '--a', type: 'int', metavar: 'A', required: true },
  { name: '--b', type: 'int', metavar: 'B', required: true },
  { name: '--c', type: 'string', metavar: 'C', required: true },
  { name: '--d', type: 'int', metavar: 'D', required: true },
  { name: '--e', type: 'string', metavar: 'E', required: true },
  { name: '--f', type: 'int', metavar: 'F', required: true },
  { name: '--g', type: 'int', metavar: 'G', required: true },
];

export const ARGUMENT_NAMES = ARGUMENT_DEFINITIONS.map((definition) => definition.name);

export const ARGUMENTS_BY_NAME = Object.fromEntries(
  ARGUMENT_DEFINITIONS.map((definition) => [definition.name, definition]),
);

export function getProgramName(argv) {
  const scriptPath = Array.isArray(argv) && argv.length > 1 ? String(argv[1]) : 'test17.mjs';
  const normalized = scriptPath.replace(/\\/g, '/');
  const parts = normalized.split('/');
  const basename = parts[parts.length - 1];
  return basename || 'test17.mjs';
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C --d D --e E --f F --g G`;
}

export function formatHelp(programName) {
  const lines = [
    formatUsage(programName),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
    '  --c C',
    '  --d D',
    '  --e E',
    '  --f F',
    '  --g G',
  ];

  return `${lines.join('\n')}\n`;
}
